SELECT c.c_customer_id, wp.wp_type, COUNT(*) AS total_returns, SUM(wr.wr_return_amt) AS total_return_amount FROM web_returns wr JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk WHERE wr.wr_returned_date_sk = 2452897 AND wp.wp_type = 'ad                                                ' GROUP BY c.c_customer_id, wp.wp_type HAVING SUM(wr.wr_return_amt) > 757.80 ORDER BY total_return_amount DESC
